<script>const themeKey='task-master-theme',toggle=document.getElementById('themeToggle'),sun='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"/></svg>',moon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 12.8A9 9 0 1 1 11.2 3 7 7 0 0 0 21 12.8Z"/></svg>';const applyTheme=theme=>{document.documentElement.dataset.theme=theme;toggle.innerHTML=theme==='dark'?sun:moon;toggle.title=theme==='dark'?'Use light theme':'Use dark theme';};const savedTheme=localStorage.getItem(themeKey),initialTheme=savedTheme||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');applyTheme(initialTheme);toggle.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';localStorage.setItem(themeKey,next);applyTheme(next);});</script>
</body>
